import {COURT,wallX} from './court-geometry.js';
export function beginPointEnd(ball,side,changed){ball.vx*=.16;ball.vz*=.16;if(ball.y>=0&&ball.y<=.11){ball.y=.095;ball.vy=Math.min(1.2,Math.abs(ball.vy)*.22);}return {side,changed,remaining:3.2};}
export function advancePointEnd(state,ball,dt){state.remaining-=dt;if(ball.y>=0){for(let left=dt;left>1e-7;){const h=Math.min(left,1/120);left-=h;ball.vy-=9.81*h;ball.x+=ball.vx*h;ball.z+=ball.vz*h;ball.y+=ball.vy*h;ball.x=Math.max(-4.7,Math.min(wallX(ball.z)-.1,ball.x));ball.z=Math.max(-COURT.endRoofInner+.1,Math.min(COURT.halfLength-.1,ball.z));if(ball.y<.095){ball.y=.095;ball.vy=Math.abs(ball.vy)*.18;ball.vx*=.6;ball.vz*=.6;if(ball.vy<.25)ball.vy=0;}const drag=Math.exp(-h*5);if(ball.y<=.096){ball.vx*=drag;ball.vz*=drag;}}}return state.remaining<=0;}
